/* ============================================================
   CommerceForge Dev Docs — Design System
   ============================================================ */

/* --- Custom Properties --- */
:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #1c2129;
  --bg-elevated: #21262d;
  --border: #30363d;
  --border-light: rgba(48, 54, 61, 0.5);
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --accent: #00dc82;
  --accent-hover: #00f59b;
  --accent-glow: rgba(0, 220, 130, 0.15);
  --accent-cyan: #39d0d8;
  --accent-blue: #58a6ff;
  --accent-purple: #a78bfa;
  --code-bg: #0a0e14;
  --card-bg: rgba(22, 27, 34, 0.7);
  --card-border: rgba(48, 54, 61, 0.5);
  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', 'Consolas', monospace;
  --radius-lg: 16px;
  --radius: 12px;
  --radius-sm: 8px;
  --radius-xs: 6px;
  --max-width: 1200px;
  --sidebar-width: 260px;
  --nav-height: 64px;
  --transition: 0.2s ease;
  --transition-slow: 0.3s ease;
}

/* --- Reset --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}
a { color: var(--accent); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent-hover); }
img { max-width: 100%; display: block; }
ul, ol { list-style: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; color: inherit; }
code { font-family: var(--font-mono); font-size: 0.9em; }

/* --- Typography --- */
h1 { font-size: clamp(2rem, 5vw, 3.25rem); font-weight: 700; line-height: 1.1; letter-spacing: -0.03em; color: var(--text-primary); }
h2 { font-size: clamp(1.5rem, 3vw, 2.25rem); font-weight: 600; line-height: 1.2; letter-spacing: -0.02em; color: var(--text-primary); }
h3 { font-size: 1.25rem; font-weight: 600; line-height: 1.3; color: var(--text-primary); }
h4 { font-size: 1rem; font-weight: 600; color: var(--text-primary); }
p { color: var(--text-secondary); line-height: 1.7; }

.section-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 0.75rem;
}

.badge {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding: 0.2em 0.7em;
  border-radius: 999px;
  background: var(--accent-glow);
  color: var(--accent);
  border: 1px solid rgba(0, 220, 130, 0.3);
}

.badge--soon {
  background: rgba(57, 208, 216, 0.1);
  color: var(--accent-cyan);
  border-color: rgba(57, 208, 216, 0.3);
}

/* --- Layout --- */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 2rem; }
.section { padding: 5rem 0; }
.section + .section { border-top: 1px solid var(--border-light); }

/* --- Grid --- */
.grid { display: grid; gap: 1.5rem; }
.grid--2 { grid-template-columns: repeat(2, 1fr); }
.grid--3 { grid-template-columns: repeat(3, 1fr); }
.grid--4 { grid-template-columns: repeat(4, 1fr); }

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  height: var(--nav-height);
  background: rgba(13, 17, 23, 0.85);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-light);
}

.nav__inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 2rem;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav__logo {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-primary);
  white-space: nowrap;
}

.nav__logo span { color: var(--accent); }

.nav__links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.nav__links a {
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 500;
  padding: 0.5rem 0.875rem;
  border-radius: var(--radius-xs);
  transition: all var(--transition);
}

.nav__links a:hover { color: var(--text-primary); background: rgba(255, 255, 255, 0.06); }
.nav__links a.active { color: var(--text-primary); }

.nav__right {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.nav__search {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.4rem 0.875rem;
  font-size: 0.8125rem;
  color: var(--text-muted);
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-xs);
  cursor: pointer;
  transition: all var(--transition);
}

.nav__search:hover { border-color: var(--text-muted); }

.nav__search svg { width: 14px; height: 14px; opacity: 0.6; }

.nav__search kbd {
  font-family: var(--font-sans);
  font-size: 0.7rem;
  padding: 0.1em 0.4em;
  background: var(--bg-tertiary);
  border-radius: 4px;
  border: 1px solid var(--border);
  color: var(--text-muted);
}

.nav__login {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary) !important;
  padding: 0.5rem 1rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-xs);
  transition: all var(--transition);
}

.nav__login:hover {
  color: var(--text-primary) !important;
  border-color: var(--text-muted);
  background: rgba(255, 255, 255, 0.04);
}

.nav__hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
}

.nav__hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--text-secondary);
  border-radius: 2px;
  transition: all var(--transition);
}

/* --- Hero --- */
.hero {
  padding: 8rem 0 5rem;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 500px;
  background: radial-gradient(ellipse, rgba(0, 220, 130, 0.08), transparent 70%);
  pointer-events: none;
}

.hero__content { position: relative; max-width: 720px; }
.hero__title { margin-bottom: 1.25rem; }
.hero__subtitle { font-size: 1.125rem; line-height: 1.7; color: var(--text-secondary); margin-bottom: 2rem; max-width: 600px; }

.hero__actions { display: flex; flex-wrap: wrap; gap: 0.75rem; }

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.875rem;
  font-weight: 500;
  padding: 0.65rem 1.25rem;
  border-radius: var(--radius-sm);
  transition: all var(--transition);
  white-space: nowrap;
}

.btn--primary {
  background: var(--accent);
  color: #0d1117;
}

.btn--primary:hover {
  background: var(--accent-hover);
  color: #0d1117;
  box-shadow: 0 0 20px rgba(0, 220, 130, 0.3);
}

.btn--secondary {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border);
}

.btn--secondary:hover {
  border-color: var(--text-muted);
  background: rgba(255, 255, 255, 0.04);
  color: var(--text-primary);
}

.btn--ghost {
  color: var(--accent);
  padding: 0.65rem 0;
}

.btn--ghost:hover { color: var(--accent-hover); }

.btn--ghost .arrow { transition: transform var(--transition); }
.btn--ghost:hover .arrow { transform: translateX(3px); }

/* --- Cards --- */
.card {
  position: relative;
  background: var(--card-bg);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid var(--card-border);
  border-radius: var(--radius);
  padding: 1.75rem;
  transition: all var(--transition-slow);
}

.card:hover {
  border-color: rgba(0, 220, 130, 0.3);
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.2), 0 0 0 1px rgba(0, 220, 130, 0.1);
  transform: translateY(-2px);
}

.card__icon {
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  margin-bottom: 1rem;
  font-size: 1.25rem;
  background: var(--accent-glow);
  color: var(--accent);
}

.card__icon--cyan { background: rgba(57, 208, 216, 0.12); color: var(--accent-cyan); }
.card__icon--blue { background: rgba(88, 166, 255, 0.12); color: var(--accent-blue); }
.card__icon--purple { background: rgba(167, 139, 250, 0.12); color: var(--accent-purple); }

.card__title { font-size: 1.125rem; font-weight: 600; margin-bottom: 0.5rem; }
.card__desc { font-size: 0.875rem; color: var(--text-secondary); line-height: 1.6; margin-bottom: 1.25rem; }
.card__link { font-size: 0.875rem; font-weight: 500; display: inline-flex; align-items: center; gap: 0.35rem; }
.card__link .arrow { transition: transform var(--transition); }
.card__link:hover .arrow { transform: translateX(3px); }

/* Product cards (larger) */
.product-card {
  padding: 2rem;
}

.product-card .card__icon {
  width: 48px;
  height: 48px;
  font-size: 1.5rem;
}

/* --- Accordion --- */
.accordion { display: flex; flex-direction: column; gap: 0; }

.accordion__item {
  border: 1px solid var(--border);
  overflow: hidden;
  transition: all var(--transition);
}

.accordion__item:first-child { border-radius: var(--radius-sm) var(--radius-sm) 0 0; }
.accordion__item:last-child { border-radius: 0 0 var(--radius-sm) var(--radius-sm); }
.accordion__item + .accordion__item { border-top: none; }

.accordion__item.open { border-color: rgba(0, 220, 130, 0.3); }
.accordion__item.open + .accordion__item { border-top: 1px solid var(--border); }

.accordion__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.25rem;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-primary);
  background: var(--bg-secondary);
  transition: background var(--transition);
  text-align: left;
}

.accordion__trigger:hover { background: var(--bg-tertiary); }

.accordion__trigger svg {
  width: 18px;
  height: 18px;
  color: var(--text-muted);
  transition: transform var(--transition);
  flex-shrink: 0;
}

.accordion__item.open .accordion__trigger svg { transform: rotate(180deg); }
.accordion__item.open .accordion__trigger { color: var(--accent); }

.accordion__body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}

.accordion__item.open .accordion__body { max-height: 600px; }

.accordion__content {
  padding: 1.25rem;
  background: var(--bg-primary);
  border-top: 1px solid var(--border-light);
}

.accordion__steps {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.accordion__step {
  display: flex;
  gap: 0.875rem;
  align-items: flex-start;
}

.step-num {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent-glow);
  color: var(--accent);
  font-size: 0.75rem;
  font-weight: 600;
  flex-shrink: 0;
  margin-top: 0.1rem;
}

.step-text { font-size: 0.875rem; color: var(--text-secondary); line-height: 1.5; }

/* --- Tabs --- */
.tabs { display: flex; flex-direction: column; }

.tabs__nav {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border);
}

.tab-btn {
  padding: 0.5rem 1rem;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--text-muted);
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: all var(--transition);
}

.tab-btn:hover { color: var(--text-secondary); }
.tab-btn.active { color: var(--accent); border-bottom-color: var(--accent); }

.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* --- Code Blocks --- */
.code-block {
  background: var(--code-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  overflow: hidden;
}

.code-block__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.5rem 1rem;
  background: rgba(22, 27, 34, 0.6);
  border-bottom: 1px solid var(--border-light);
  font-size: 0.75rem;
  color: var(--text-muted);
}

.code-block__copy {
  font-size: 0.75rem;
  color: var(--text-muted);
  padding: 0.25rem 0.5rem;
  border-radius: var(--radius-xs);
  transition: all var(--transition);
}

.code-block__copy:hover { color: var(--text-secondary); background: rgba(255, 255, 255, 0.06); }

.code-block pre {
  padding: 1rem;
  overflow-x: auto;
  font-family: var(--font-mono);
  font-size: 0.8125rem;
  line-height: 1.6;
  color: var(--text-primary);
}

.code-block pre .prompt { color: var(--accent); user-select: none; }
.code-block pre .flag { color: var(--accent-cyan); }
.code-block pre .string { color: #a5d6ff; }
.code-block pre .comment { color: var(--text-muted); font-style: italic; }

/* --- Sidebar (docs layout) --- */
.docs-layout {
  display: flex;
  padding-top: var(--nav-height);
  min-height: 100vh;
}

.sidebar {
  position: fixed;
  top: var(--nav-height);
  left: 0;
  bottom: 0;
  width: var(--sidebar-width);
  background: var(--bg-secondary);
  border-right: 1px solid var(--border);
  overflow-y: auto;
  padding: 1.5rem 0;
  transition: transform var(--transition-slow), width var(--transition-slow);
  z-index: 50;
}

.sidebar__section { margin-bottom: 1.5rem; }

.sidebar__heading {
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-muted);
  padding: 0 1.25rem;
  margin-bottom: 0.5rem;
}

.sidebar__link {
  display: block;
  font-size: 0.8125rem;
  color: var(--text-secondary);
  padding: 0.375rem 1.25rem;
  border-left: 2px solid transparent;
  transition: all var(--transition);
}

.sidebar__link:hover { color: var(--text-primary); background: rgba(255, 255, 255, 0.03); }
.sidebar__link.active { color: var(--accent); border-left-color: var(--accent); background: var(--accent-glow); }

.sidebar-toggle {
  position: fixed;
  top: calc(var(--nav-height) + 1rem);
  left: calc(var(--sidebar-width) - 12px);
  z-index: 55;
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: 50%;
  color: var(--text-muted);
  font-size: 0.75rem;
  transition: all var(--transition-slow);
}

.sidebar-toggle:hover { color: var(--text-primary); border-color: var(--text-muted); }

.docs-main {
  flex: 1;
  margin-left: var(--sidebar-width);
  padding: 2.5rem 3rem;
  max-width: calc(var(--max-width) - var(--sidebar-width));
  transition: margin-left var(--transition-slow);
}

.docs-layout.sidebar-collapsed .sidebar { transform: translateX(-100%); }
.docs-layout.sidebar-collapsed .sidebar-toggle { left: 0; }
.docs-layout.sidebar-collapsed .sidebar-toggle svg { transform: rotate(180deg); }
.docs-layout.sidebar-collapsed .docs-main { margin-left: 0; }

/* --- Section Header (docs pages) --- */
.section-header { margin-bottom: 2.5rem; }
.section-header p { margin-top: 0.75rem; max-width: 600px; }

/* --- Feature Grid --- */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.25rem;
}

.feature-card {
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: var(--radius-sm);
  padding: 1.5rem;
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: rgba(0, 220, 130, 0.2);
  background: rgba(22, 27, 34, 0.9);
}

.feature-card h4 { margin-bottom: 0.5rem; }
.feature-card p { font-size: 0.8125rem; line-height: 1.6; }

/* --- Launch CTA Section --- */
.launch-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
}

.launch-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 2rem;
  transition: all var(--transition);
}

.launch-card:hover { border-color: rgba(0, 220, 130, 0.25); }
.launch-card h3 { margin-bottom: 0.5rem; }
.launch-card p { font-size: 0.875rem; margin-bottom: 1.25rem; }

/* --- Community Section --- */
.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.25rem;
}

.community-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: var(--radius-sm);
  padding: 1.5rem;
  transition: all var(--transition);
}

.community-card:hover {
  border-color: var(--accent-cyan);
  transform: translateY(-2px);
}

.community-card__icon {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-xs);
  background: rgba(57, 208, 216, 0.1);
  color: var(--accent-cyan);
  font-size: 1rem;
  margin-bottom: 0.875rem;
}

.community-card h4 { font-size: 0.9375rem; margin-bottom: 0.375rem; }
.community-card p { font-size: 0.8125rem; color: var(--text-muted); flex-grow: 1; margin-bottom: 1rem; }
.community-card .card__link { font-size: 0.8125rem; margin-top: auto; }

/* --- Protocol actors (agents page) --- */
.actors-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.25rem;
  margin-top: 2rem;
}

.actor-card {
  text-align: center;
  padding: 2rem 1.25rem;
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: var(--radius);
  transition: all var(--transition);
}

.actor-card:hover { border-color: rgba(0, 220, 130, 0.25); }

.actor-card__icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  font-size: 1.5rem;
  background: var(--accent-glow);
  color: var(--accent);
}

.actor-card h4 { margin-bottom: 0.375rem; }
.actor-card p { font-size: 0.8125rem; }

/* --- How it works (agents page) --- */
.how-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.5rem;
  margin-top: 2rem;
}

.how-card {
  padding: 2rem;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius);
}

.how-card h3 { margin-bottom: 0.5rem; display: flex; align-items: center; gap: 0.5rem; }
.how-card p { font-size: 0.875rem; }

/* --- Support Categories --- */
.support-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1.25rem;
}

.support-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.75rem;
  transition: all var(--transition);
}

.support-card:hover { border-color: rgba(0, 220, 130, 0.2); }
.support-card h4 { margin-bottom: 0.75rem; }
.support-card ul { display: flex; flex-direction: column; gap: 0.375rem; }
.support-card li { font-size: 0.875rem; color: var(--text-secondary); padding-left: 1rem; position: relative; }
.support-card li::before { content: ''; position: absolute; left: 0; top: 0.6em; width: 4px; height: 4px; border-radius: 50%; background: var(--text-muted); }

/* --- Footer --- */
.footer {
  border-top: 1px solid var(--border);
  padding: 4rem 0 2.5rem;
  background: var(--bg-secondary);
}

.footer__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  margin-bottom: 3rem;
}

.footer__col h4 {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer__col a {
  display: block;
  font-size: 0.8125rem;
  color: var(--text-muted);
  padding: 0.25rem 0;
  transition: color var(--transition);
}

.footer__col a:hover { color: var(--text-primary); }

.footer__bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 2rem;
  border-top: 1px solid var(--border-light);
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .grid--3, .feature-grid { grid-template-columns: repeat(2, 1fr); }
