}

/* --- Accordion --- */
.accordion { display: flex; flex-direction: column; gap: 0; }

.accordion__item {
  border: 1px solid var(--border);
  overflow: hidden;
  transition: all var(--transition);
}

.accordion__item:first-child { border-radius: var(--radius-sm) var(--radius-sm) 0 0; }
.accordion__item:last-child { border-radius: 0 0 var(--radius-sm) var(--radius-sm); }
.accordion__item + .accordion__item { border-top: none; }

.accordion__item.open { border-color: rgba(0, 220, 130, 0.3); }
.accordion__item.open + .accordion__item { border-top: 1px solid var(--border); }

.accordion__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.25rem;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-primary);
  background: var(--bg-secondary);
  transition: background var(--transition);
  text-align: left;
}

.accordion__trigger:hover { background: var(--bg-tertiary); }

.accordion__trigger svg {
  width: 18px;
  height: 18px;
  color: var(--text-muted);
  transition: transform var(--transition);
  flex-shrink: 0;
}

.accordion__item.open .accordion__trigger svg { transform: rotate(180deg); }
.accordion__item.open .accordion__trigger { color: var(--accent); }

.accordion__body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}

.accordion__item.open .accordion__body { max-height: 600px; }

.accordion__content {
  padding: 1.25rem;
  background: var(--bg-primary);
  border-top: 1px solid var(--border-light);
}

.accordion__steps {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 1.25rem;
}

.accordion__step {
  display: flex;
  gap: 0.875rem;
  align-items: flex-start;
}

.step-num {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent-glow);
  color: var(--accent);
  font-size: 0.75rem;
  font-weight: 600;
  flex-shrink: 0;
  margin-top: 0.1rem;
}

.step-text { font-size: 0.875rem; color: var(--text-secondary); line-height: 1.5; }

/* --- Tabs --- */
.tabs { display: flex; flex-direction: column; }

.tabs__nav {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border);
}

.tab-btn {
  padding: 0.5rem 1rem;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--text-muted);
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
